//! The hidden `mock-server` subcommand: a stdio MCP server that answers `tools/call`
//! straight out of a resolved `MockSet`, materialized to disk by `trg ai skills eval run`.
//!
//! Hidden from `--help` because operators never invoke it directly; `--mcp-config`
//! generated by a run points a harness at this same binary with the right flags.
//!
//! Only `initialize`, `tools/list`, and `tools/call` are implemented. Everything else
//! gets a proper JSON-RPC method-not-found error rather than being silently ignored, so a
//! harness that depends on a method this mock does not answer fails loudly instead of
//! hanging. A hand-rolled loop over plain `serde_json::Value` was chosen over reusing
//! `rmcp`'s client-role transport types (the precedent in `commands/mcp/proxy/run.rs`):
//! those types are shaped around being the client half of the protocol, and bending them
//! into a from-scratch server for three methods would cost more than it saves.

mod constants;
use crate::exit_code::ExitCode;
use constants::{DURATION_BUCKETS, INVALID_PARAMS, METHOD_NOT_FOUND, MOCK_SUBSTITUTION_FAILED, PIPE, TOOL_ERROR};
use std::collections::BTreeMap;
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::{Path, PathBuf};
use std::time::Instant;

use clap::Args;
use opentelemetry::metrics::{Histogram, Meter};
use opentelemetry::KeyValue;
use opentelemetry_semantic_conventions::attribute::{
    ERROR_TYPE, JSONRPC_REQUEST_ID, NETWORK_TRANSPORT, RPC_RESPONSE_STATUS_CODE,
};
use serde::Serialize;
use serde_json::Value;
use tracing::field::Empty;

use crate::agentskills::mocks::{
    resolve_call, MockCallAnswer, MockCallLogEntry, MockCallTimestamp, MockDeclaration, ServerName, ToolName,
};
use crate::telemetry::semconv::generated::attributes::{
    gen_ai_operation_name, mcp_method_name, GEN_AI_OPERATION_NAME, GEN_AI_TOOL_NAME, MCP_METHOD_NAME,
};
use crate::telemetry::semconv::generated::metrics::MCP_SERVER_OPERATION_DURATION;
use crate::telemetry::semconv::trg::{EVAL_MOCK_MATCH, EVAL_MOCK_SERVER};

#[derive(Serialize)]
struct RpcSuccess<R> {
    jsonrpc: &'static str,
    id: Value,
    result: R,
}

#[derive(Serialize)]
struct RpcFailure {
    jsonrpc: &'static str,
    id: Value,
    error: RpcFailureDetails,
}

#[derive(Serialize)]
struct RpcFailureDetails {
    code: i64,
    message: String,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct InitializationResult {
    protocol_version: Value,
    capabilities: ToolCapabilities,
    server_info: ServerInfo,
}

#[derive(Serialize)]
struct ToolCapabilities {
    tools: BTreeMap<String, Value>,
}

#[derive(Serialize)]
struct ServerInfo {
    name: &'static str,
    version: &'static str,
}

#[derive(Serialize)]
struct ListedTool<'a> {
    name: &'a str,
    #[serde(rename = "inputSchema")]
    input_schema: ToolInputSchema,
}

#[derive(Serialize)]
struct ToolInputSchema {
    #[serde(rename = "type")]
    kind: &'static str,
}

#[derive(Serialize)]
struct ListedTools<'a> {
    tools: Vec<ListedTool<'a>>,
}

#[derive(Serialize)]
struct ToolText {
    #[serde(rename = "type")]
    kind: &'static str,
    text: String,
}

#[derive(Serialize)]
struct ToolResult {
    content: [ToolText; 1],
    #[serde(rename = "isError")]
    is_error: bool,
}

/// `trg ai skills eval mock-server` flags. Not meant to be typed by hand: a run's
/// generated `--mcp-config` is the only caller.
#[derive(Args, Debug, Clone)]
pub struct MockServerArgs {
    /// Directory holding this server's resolved mock declarations, one `<tool>.json` file
    /// per tool.
    #[arg(long)]
    pub mocks_dir: PathBuf,
    /// The server name this process answers as, for the calls it logs.
    #[arg(long)]
    pub server: String,
    /// Where to append one JSON line per `tools/call`, violations included.
    #[arg(long)]
    pub calls_file: PathBuf,
}

impl MockServerArgs {
    #[cfg_attr(
        dylint_lib = "trogon_dylint_lints",
        expect(
            debug_remnants,
            reason = "This function renders the CLI response or an operator action on its designated stream; tracing must not replace that output"
        )
    )]
    pub fn handle(self) -> ExitCode {
        let server = ServerName::from(self.server.as_str());
        let tools = match load_server_mocks(&self.mocks_dir) {
            Ok(tools) => tools,
            Err(e) => {
                eprintln!(
                    "mock-server: failed to load mocks from {}: {}",
                    self.mocks_dir.display(),
                    e
                );
                return ExitCode::InfrastructureFailure;
            }
        };
        if let Err(e) = open_call_log(&self.calls_file) {
            eprintln!(
                "mock-server: failed to open the call log at {}: {}",
                self.calls_file.display(),
                e
            );
            return ExitCode::InfrastructureFailure;
        }

        let stdin = io::stdin();
        let stdout = io::stdout();
        let durations = OperationDuration::on(&opentelemetry::global::meter("trg"));
        match run_stdio_loop(
            stdin.lock(),
            stdout.lock(),
            &server,
            &tools,
            &self.calls_file,
            &durations,
        ) {
            Ok(()) => ExitCode::Success,
            Err(e) => {
                eprintln!("mock-server: {e}");
                ExitCode::InfrastructureFailure
            }
        }
    }
}

/// The call log exists from the moment a server has its mocks, and not one step earlier.
///
/// Created here rather than when the mock set was materialized, because a file written
/// before the server came up is still there when it never comes up at all, and a grader
/// that reads it empty would report a run whose agent called nothing where in truth
/// nothing was ever able to answer a call. Its absence is the only signal that says so.
fn open_call_log(path: &Path) -> io::Result<()> {
    fs::OpenOptions::new().create(true).append(true).open(path).map(|_| ())
}

fn load_server_mocks(mocks_dir: &PathBuf) -> io::Result<BTreeMap<ToolName, MockDeclaration>> {
    let mut tools = BTreeMap::new();
    for entry in fs::read_dir(mocks_dir)? {
        let path = entry?.path();
        if path.extension().and_then(|e| e.to_str()) != Some("json") {
            continue;
        }
        let tool_name = path.file_stem().and_then(|s| s.to_str()).unwrap_or_default();
        let content = fs::read_to_string(&path)?;
        let declaration: MockDeclaration = serde_json::from_str(&content)
            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, format!("{}: {e}", path.display())))?;
        tools.insert(ToolName::from(tool_name), declaration);
    }
    Ok(tools)
}

/// Read newline-delimited JSON-RPC requests until stdin closes, answering each on stdout.
/// A notification (no `id`) is handled but never answered, per JSON-RPC 2.0.
fn run_stdio_loop(
    reader: impl BufRead,
    mut writer: impl Write,
    server: &ServerName,
    tools: &BTreeMap<ToolName, MockDeclaration>,
    calls_log_path: &PathBuf,
    durations: &OperationDuration,
) -> io::Result<()> {
    for line in reader.lines() {
        let line = line?;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let request: Value = match serde_json::from_str(trimmed) {
            Ok(value) => value,
            Err(_) => continue,
        };
        if let Some(response) = handle_request(&request, server, tools, calls_log_path, durations)? {
            let mut serialized = serde_json::to_string(&response)?;
            serialized.push('\n');
            writer.write_all(serialized.as_bytes())?;
            writer.flush()?;
        }
    }
    Ok(())
}

/// Answer one JSON-RPC request, or return `None` for a notification (no `id`), which
/// JSON-RPC 2.0 forbids answering at all.
fn handle_request(
    request: &Value,
    server: &ServerName,
    tools: &BTreeMap<ToolName, MockDeclaration>,
    calls_log_path: &PathBuf,
    durations: &OperationDuration,
) -> io::Result<Option<Value>> {
    let Some(id) = request.get("id").cloned() else {
        return Ok(None);
    };
    let received = Instant::now();
    let method = request.get("method").and_then(Value::as_str).unwrap_or_default();
    let tool = called_tool(request, method);
    let span = request_span(method, tool, &id, server);
    let mut matched = None;

    let response = span
        .in_scope(|| -> io::Result<Value> {
            Ok(match method {
                "initialize" => {
                    let protocol_version = request
                        .pointer("/params/protocolVersion")
                        .cloned()
                        .unwrap_or_else(|| Value::String("2024-11-05".to_string()));
                    success(
                        id,
                        InitializationResult {
                            protocol_version,
                            capabilities: ToolCapabilities { tools: BTreeMap::new() },
                            server_info: ServerInfo {
                                name: "trg-mock-server",
                                version: env!("CARGO_PKG_VERSION"),
                            },
                        },
                    )
                }
                "tools/list" => {
                    let tool_list = tools
                        .keys()
                        .map(|tool| ListedTool {
                            name: tool.as_str(),
                            input_schema: ToolInputSchema { kind: "object" },
                        })
                        .collect();
                    success(id, ListedTools { tools: tool_list })
                }
                "tools/call" => {
                    let tool_name = request
                        .pointer("/params/name")
                        .and_then(Value::as_str)
                        .unwrap_or_default();
                    let arguments = request
                        .pointer("/params/arguments")
                        .cloned()
                        .unwrap_or(Value::Object(serde_json::Map::new()));
                    match tools.get(&ToolName::from(tool_name)) {
                        None => {
                            matched = Some(MockMatch::UnknownTool);
                            error(id, INVALID_PARAMS, format!("unknown tool `{tool_name}`"))
                        }
                        Some(declaration) => {
                            let received_at = MockCallTimestamp::now();
                            let tool = ToolName::from(tool_name);
                            let outcome = resolve_call(declaration, server, &tool, &arguments);
                            matched = Some(MockMatch::of(&outcome.answer, outcome.violations.is_empty()));
                            append_call_log(
                                calls_log_path,
                                &MockCallLogEntry {
                                    server: server.clone(),
                                    tool,
                                    input: arguments,
                                    violations: outcome.violations,
                                    received_at: Some(received_at),
                                },
                            )?;
                            match outcome.answer {
                                MockCallAnswer::Answered { text, is_error } => success(
                                    id,
                                    ToolResult {
                                        content: [ToolText { kind: "text", text }],
                                        is_error,
                                    },
                                ),
                                MockCallAnswer::Unresolved(unresolved) => {
                                    error(id, MOCK_SUBSTITUTION_FAILED, unresolved.to_string())
                                }
                            }
                        }
                    }
                }
                other => error(id, METHOD_NOT_FOUND, format!("method not found: {other}")),
            })
        })
        .inspect_err(|error| {
            let failure = Failure {
                error_type: format!("{:?}", error.kind()),
                status_code: None,
            };
            span.record("otel.status_code", "ERROR");
            span.record(ERROR_TYPE, failure.error_type.as_str());
            durations.record(received, method, tool, Some(&failure));
        })?;

    let failure = record_response(&span, method, &response, matched);
    durations.record(received, method, tool, failure.as_ref());
    Ok(Some(response))
}

/// `mcp.server.operation.duration`, recorded once for every request this server answers.
struct OperationDuration(Histogram<f64>);

impl OperationDuration {
    fn on(meter: &Meter) -> Self {
        Self(
            meter
                .f64_histogram(MCP_SERVER_OPERATION_DURATION)
                .with_unit("s")
                .with_description(
                    "MCP request or notification duration as observed on the receiver from the time it was \
                     received until the result or ack is sent.",
                )
                .with_boundaries(DURATION_BUCKETS.to_vec())
                .build(),
        )
    }

    fn record(&self, received: Instant, method: &str, tool: Option<&str>, failure: Option<&Failure>) {
        let mut attributes = vec![
            KeyValue::new(MCP_METHOD_NAME, method.to_string()),
            KeyValue::new(NETWORK_TRANSPORT, PIPE),
        ];
        if let Some(tool) = tool {
            attributes.push(KeyValue::new(
                GEN_AI_OPERATION_NAME,
                gen_ai_operation_name::EXECUTE_TOOL,
            ));
            attributes.push(KeyValue::new(GEN_AI_TOOL_NAME, tool.to_string()));
        }
        if let Some(failure) = failure {
            if let Some(code) = &failure.status_code {
                attributes.push(KeyValue::new(RPC_RESPONSE_STATUS_CODE, code.clone()));
            }
            attributes.push(KeyValue::new(ERROR_TYPE, failure.error_type.clone()));
        }
        self.0.record(received.elapsed().as_secs_f64(), &attributes);
    }
}

/// Why a request did not succeed, as its span and its duration both report it.
struct Failure {
    error_type: String,
    status_code: Option<String>,
}

/// How a mocked `tools/call` met its declaration, so a trace tells a call the agent got
/// right from one the mock answered anyway.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MockMatch {
    Matched,
    Violated,
    Unresolved,
    UnknownTool,
}

impl MockMatch {
    fn of(answer: &MockCallAnswer, satisfied: bool) -> Self {
        match (answer, satisfied) {
            (MockCallAnswer::Unresolved(_), _) => Self::Unresolved,
            (_, true) => Self::Matched,
            (_, false) => Self::Violated,
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Matched => "matched",
            Self::Violated => "violated",
            Self::Unresolved => "unresolved",
            Self::UnknownTool => "unknown_tool",
        }
    }
}

fn called_tool<'a>(request: &'a Value, method: &str) -> Option<&'a str> {
    (method == mcp_method_name::TOOLS_CALL)
        .then(|| request.pointer("/params/name").and_then(Value::as_str))
        .flatten()
}

/// The MCP SERVER span for one request, named `{mcp.method.name} {tool}` for a tool call.
fn request_span(method: &str, tool: Option<&str>, id: &Value, server: &ServerName) -> tracing::Span {
    let name = match tool {
        Some(tool) => format!("{method} {tool}"),
        None => method.to_string(),
    };
    let request_id = match id {
        Value::String(text) => text.clone(),
        other => other.to_string(),
    };
    tracing::info_span!(
        "mcp request",
        "otel.name" = name,
        "otel.kind" = "server",
        "otel.status_code" = Empty,
        { MCP_METHOD_NAME } = method,
        { JSONRPC_REQUEST_ID } = request_id,
        { GEN_AI_TOOL_NAME } = tool,
        { GEN_AI_OPERATION_NAME } = tool.map(|_| gen_ai_operation_name::EXECUTE_TOOL),
        { EVAL_MOCK_SERVER } = server.as_str(),
        { EVAL_MOCK_MATCH } = Empty,
        { RPC_RESPONSE_STATUS_CODE } = Empty,
        { ERROR_TYPE } = Empty,
    )
}

fn record_response(
    span: &tracing::Span,
    method: &str,
    response: &Value,
    matched: Option<MockMatch>,
) -> Option<Failure> {
    if let Some(matched) = matched {
        span.record(EVAL_MOCK_MATCH, matched.as_str());
    }
    let failure = if let Some(code) = response.pointer("/error/code").and_then(Value::as_i64) {
        let code = code.to_string();
        span.record(RPC_RESPONSE_STATUS_CODE, code.as_str());
        Failure {
            error_type: code.clone(),
            status_code: Some(code),
        }
    } else if method == mcp_method_name::TOOLS_CALL
        && response.pointer("/result/isError").and_then(Value::as_bool) == Some(true)
    {
        Failure {
            error_type: TOOL_ERROR.to_string(),
            status_code: None,
        }
    } else {
        return None;
    };
    span.record("otel.status_code", "ERROR");
    span.record(ERROR_TYPE, failure.error_type.as_str());
    Some(failure)
}

fn append_call_log(path: &PathBuf, entry: &MockCallLogEntry) -> io::Result<()> {
    let mut line = serde_json::to_string(entry)?;
    line.push('\n');
    let mut file = fs::OpenOptions::new().create(true).append(true).open(path)?;
    file.write_all(line.as_bytes())
}

fn success(id: Value, result: impl Serialize) -> Value {
    serde_json::to_value(RpcSuccess {
        jsonrpc: "2.0",
        id,
        result,
    })
    .expect("mock responses contain only JSON values")
}

fn error(id: Value, code: i64, message: String) -> Value {
    serde_json::to_value(RpcFailure {
        jsonrpc: "2.0",
        id,
        error: RpcFailureDetails { code, message },
    })
    .expect("mock errors contain only JSON values")
}

